const raw = $input.first().json;
const body = raw.body || raw;

// Handle Time Diary entries
if (body.type === 'time_diary') {
  const name = body.name || 'Неизвестно';
  const date = body.date || 'Неизвестно';
  const entries = body.entries || {};

  let entriesText = '';
  const hours = Object.keys(entries).sort();
  for (const hour of hours) {
    entriesText += `${hour} — ${entries[hour]}\n`;
  }

  // Calculate summary
  const summary = {};
  for (const task of Object.values(entries)) {
    const key = task.toLowerCase();
    summary[key] = (summary[key] || 0) + 1;
  }
  const summaryText = Object.entries(summary)
    .sort((a, b) => b[1] - a[1])
    .map(([task, hours]) => `${hours}ч ${task}`)
    .join(', ');

  const message = `⏱️ Дневник времени\n\n👤 ${name}\n📅 ${date}\n\n${entriesText}\n📊 Итого: ${summaryText}`;

  return { json: { message } };
}

// Handle Audit Forms
const roleNames = {
  dasha: '👩‍💼 Даша',
  pasha: '👨‍💼 Паша',
  backoffice: '📋 Бэкофис',
  accountant: '📊 Надя'
};

const role = body.role || 'unknown';
const roleName = roleNames[role] || role;
const timestamp = new Date(body.timestamp).toLocaleString('ru-RU', {timeZone: 'Europe/Minsk'});

let answersText = '';
const answers = body.answers || {};

for (const [question, value] of Object.entries(answers)) {
  let displayValue = value;

  if (Array.isArray(value)) {
    displayValue = value.join(', ') || '—';
  } else if (typeof value === 'object' && value !== null) {
    displayValue = Object.entries(value)
      .filter(([k, v]) => v)
      .map(([k, v]) => `${k}: ${v}`)
      .join('; ') || '—';
  }

  if (displayValue) {
    // Shorten question for readability
    const shortQ = question.length > 50 ? question.slice(0, 47) + '...' : question;
    answersText += `❓ ${shortQ}\n➡️ ${displayValue}\n\n`;
  }
}

const message = `🔔 Анкета: ${roleName}\n🕐 ${timestamp}\n\n${answersText.slice(0, 3500)}`;

return {
  json: {
    message,
    role,
    timestamp: body.timestamp,
    answers: body.answers
  }
};
